insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-el-chavo-del-8-trivia',
  'El Chavo del 8 Trivia: Vecindad, Characters and Quotes',
  'The boy in the barrel, the neighbor who owes fourteen months of rent and a courtyard every Latin American home knows: El Chavo del 8, Chespirito''s beloved Mexican sitcom. How many characters and quotes do you remember?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"Who created El Chavo del 8 and played the boy himself?","options":[{"id":"a","text":"Carlos Villagrán","is_correct":false},{"id":"b","text":"Ramón Valdés","is_correct":false},{"id":"c","text":"Roberto Gómez Bolaños ''Chespirito''","is_correct":true},{"id":"d","text":"Édgar Vivar","is_correct":false}],"explanation":"Roberto Gómez Bolaños, known as Chespirito, created the series and played the Chavo himself."},{"id":"q2","question":"Inside the vecindad, where does the Chavo live?","options":[{"id":"a","text":"In a barrel","is_correct":true},{"id":"b","text":"In the building''s laundry room","is_correct":false},{"id":"c","text":"Under the courtyard staircase","is_correct":false},{"id":"d","text":"In a treehouse","is_correct":false}],"explanation":"The barrel in the middle of the courtyard is his home — and the show''s most famous prop."},{"id":"q3","question":"Which actor played Don Ramón, the neighbor who never pays his rent?","options":[{"id":"a","text":"Rubén Aguirre","is_correct":false},{"id":"b","text":"Ramón Valdés","is_correct":true},{"id":"c","text":"Édgar Vivar","is_correct":false},{"id":"d","text":"Carlos Villagrán","is_correct":false}],"explanation":"Ramón Valdés played Don Ramón and left a permanent mark on Latin American comedy."},{"id":"q4","question":"What food does the Chavo daydream about all the time?","options":[{"id":"a","text":"Chocolate cake","is_correct":false},{"id":"b","text":"Chicken tacos","is_correct":false},{"id":"c","text":"Lollipops","is_correct":false},{"id":"d","text":"Ham sandwiches","is_correct":true}],"explanation":"His eternal craving: ham sandwiches — tortas de jamón."},{"id":"q5","question":"How many months of rent does Don Ramón owe Señor Barriga?","options":[{"id":"a","text":"Six","is_correct":false},{"id":"b","text":"Fourteen","is_correct":true},{"id":"c","text":"Twenty","is_correct":false},{"id":"d","text":"Thirty-six","is_correct":false}],"explanation":"The running gag is always the same number: fourteen months of rent."},{"id":"q6","question":"Which neighbor slaps Don Ramón almost every time he crosses her path?","options":[{"id":"a","text":"Doña Clotilde","is_correct":false},{"id":"b","text":"La Chilindrina","is_correct":false},{"id":"c","text":"Doña Florinda","is_correct":true},{"id":"d","text":"La Popis","is_correct":false}],"explanation":"Doña Florinda, Quico''s mother, always assumes Don Ramón did something to her son — and slaps him."},{"id":"q7","question":"Which of these phrases belongs to the Chavo?","options":[{"id":"a","text":"''¡No me simpatizas!''","is_correct":false},{"id":"b","text":"''¡Fue sin querer queriendo!''","is_correct":true},{"id":"c","text":"''¡Ta ta ta ta tá!''","is_correct":false},{"id":"d","text":"''¡No contaban con mi astucia!''","is_correct":false}],"explanation":"''¡Fue sin querer queriendo!'' is his signature line; the first is Quico''s, ''ta ta ta'' is Professor Jirafales'' outburst and the last is El Chapulín Colorado''s."},{"id":"q8","question":"Édgar Vivar plays two characters in the series: Ñoño and...","options":[{"id":"a","text":"Profesor Jirafales","is_correct":false},{"id":"b","text":"Señor Barriga","is_correct":true},{"id":"c","text":"Godínez","is_correct":false},{"id":"d","text":"Jaimito el Cartero","is_correct":false}],"explanation":"Édgar Vivar doubles as Ñoño and as Señor Barriga, the landlord who comes to collect the rent."}]'::jsonb,
  null,
  array['el chavo', 'tv-shows', 'comedy', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
