values (
  'es-trivia-el-chavo-del-8',
  'Trivia de El Chavo del 8: la vecindad, personajes y frases',
  'El niño del barril, Don Ramón y la vecindad que toda Latinoamérica conoce: la comedia de Chespirito que crió a generaciones. ¿Cuántos personajes y frases recuerdas?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"¿Quién creó El Chavo del 8 e interpreta al propio Chavo?","options":[{"id":"a","text":"Ramón Valdés","is_correct":false},{"id":"b","text":"Roberto Gómez Bolaños ''Chespirito''","is_correct":true},{"id":"c","text":"Carlos Villagrán","is_correct":false},{"id":"d","text":"Rubén Aguirre","is_correct":false}],"explanation":"Roberto Gómez Bolaños, Chespirito, creó el programa y le dio vida al Chavo."},{"id":"q2","question":"¿Dónde vive el Chavo dentro de la vecindad?","options":[{"id":"a","text":"En un barril","is_correct":true},{"id":"b","text":"En la lavandería","is_correct":false},{"id":"c","text":"Debajo de la escalera del patio","is_correct":false},{"id":"d","text":"En la azotea","is_correct":false}],"explanation":"El barril en medio del patio es su casa y el símbolo más famoso de la serie."},{"id":"q3","question":"¿Cuántos meses de renta le debe Don Ramón al Señor Barriga?","options":[{"id":"a","text":"Seis","is_correct":false},{"id":"b","text":"Catorce","is_correct":true},{"id":"c","text":"Veinticuatro","is_correct":false},{"id":"d","text":"Cinco","is_correct":false}],"explanation":"El chiste corre con el mismo número en todos los episodios: catorce meses."},{"id":"q4","question":"¿Qué actor interpreta a Don Ramón?","options":[{"id":"a","text":"Édgar Vivar","is_correct":false},{"id":"b","text":"Rubén Aguirre","is_correct":false},{"id":"c","text":"Ramón Valdés","is_correct":true},{"id":"d","text":"Horacio Gómez Bolaños","is_correct":false}],"explanation":"Ramón Valdés le dio vida a Don Ramón; Horacio Gómez Bolaños interpretaba a Godínez."},{"id":"q5","question":"¿Qué comida sueña con comer el Chavo todo el tiempo?","options":[{"id":"a","text":"Tortas de jamón","is_correct":true},{"id":"b","text":"Pasteles de chocolate","is_correct":false},{"id":"c","text":"Tacos de pollo","is_correct":false},{"id":"d","text":"Paletas","is_correct":false}],"explanation":"Las tortas de jamón son su antojo eterno."},{"id":"q6","question":"¿Qué dos personajes interpreta Édgar Vivar?","options":[{"id":"a","text":"Quico y Godínez","is_correct":false},{"id":"b","text":"Ñoño y el Señor Barriga","is_correct":true},{"id":"c","text":"Don Ramón y el Profesor Jirafales","is_correct":false},{"id":"d","text":"El Chavo y Jaimito el Cartero","is_correct":false}],"explanation":"Édgar Vivar hace doble papel: Ñoño y el Señor Barriga, el dueño de la vecindad."},{"id":"q7","question":"¿Cómo conocen los niños a Doña Clotilde?","options":[{"id":"a","text":"La loca de la escalera","is_correct":false},{"id":"b","text":"La Bruja del 71","is_correct":true},{"id":"c","text":"La reina del patio","is_correct":false},{"id":"d","text":"La vecina de enfrente","is_correct":false}],"explanation":"La llaman ''la Bruja del 71'' por vivir en el departamento 71; la interpreta Angelines Fernández."},{"id":"q8","question":"¿Cuál es la frase característica de Quico?","options":[{"id":"a","text":"''¡No me simpatizas!''","is_correct":true},{"id":"b","text":"''¡Fue sin querer queriendo!''","is_correct":false},{"id":"c","text":"''¡Se me chispoteó!''","is_correct":false},{"id":"d","text":"''¡Tenía que ser el Chavo del 8!''","is_correct":false}],"explanation":"''¡No me simpatizas!'' es de Quico; las otras tres frases son del Chavo."}]'::jsonb,
  null,
  array['el chavo', 'series', 'comedia', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
