insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-el-chapulin-colorado-trivia',
  'El Chapulín Colorado Trivia: Heroes and Catchphrases',
  'More agile than a turtle, stronger than a mouse, nobler than lettuce: El Chapulín Colorado, Chespirito''s clumsy red-and-yellow superhero. Test your memory of his gadgets and catchphrases.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"Who created and played El Chapulín Colorado?","options":[{"id":"a","text":"Édgar Vivar","is_correct":false},{"id":"b","text":"Roberto Gómez Bolaños ''Chespirito''","is_correct":true},{"id":"c","text":"Ramón Valdés","is_correct":false},{"id":"d","text":"Rubén Aguirre","is_correct":false}],"explanation":"Roberto Gómez Bolaños — the same Chespirito behind El Chavo del 8 — played the clumsy superhero."},{"id":"q2","question":"What colors is the Chapulín''s costume?","options":[{"id":"a","text":"Blue and gold","is_correct":false},{"id":"b","text":"Red and yellow","is_correct":true},{"id":"c","text":"Green and white","is_correct":false},{"id":"d","text":"Black and silver","is_correct":false}],"explanation":"Red and yellow, with a heart on the chest: the most recognizable superhero outfit on Latin TV."},{"id":"q3","question":"What does the Chapulín wear on his chest?","options":[{"id":"a","text":"A lightning bolt","is_correct":false},{"id":"b","text":"A red grasshopper","is_correct":false},{"id":"c","text":"A yellow star","is_correct":false},{"id":"d","text":"A heart with the letters CH","is_correct":true}],"explanation":"His shield is a heart — literally: the costume''s emblem is a heart with the initials CH."},{"id":"q4","question":"What does the Chapulín announce when he shows up to save the day?","options":[{"id":"a","text":"''¡No contaban con mi astucia!''","is_correct":true},{"id":"b","text":"''¡Fue sin querer queriendo!''","is_correct":false},{"id":"c","text":"''¡No me simpatizas!''","is_correct":false},{"id":"d","text":"''¡Ta ta ta ta tá!''","is_correct":false}],"explanation":"He shouts ''¡No contaban con mi astucia!'' the moment he appears; the other lines belong to El Chavo, Quico and Professor Jirafales."},{"id":"q5","question":"The Chapulín''s trusty weapon, the Chipote Chillón, is...","options":[{"id":"a","text":"A squeaky little hammer","is_correct":true},{"id":"b","text":"A magic sword","is_correct":false},{"id":"c","text":"A wooden slingshot","is_correct":false},{"id":"d","text":"A rubber boomerang","is_correct":false}],"explanation":"The Chipote Chillón is a small toy-like hammer he swings at villains — when he manages not to hit himself."},{"id":"q6","question":"What do the Chapulín''s ''pastillas de chiquitina'' do?","options":[{"id":"a","text":"Make him invisible","is_correct":false},{"id":"b","text":"Shrink him to the size of a doll","is_correct":true},{"id":"c","text":"Make him fly","is_correct":false},{"id":"d","text":"Put his enemies to sleep","is_correct":false}],"explanation":"The ''chiquitina'' pills shrink him — handy against enemies that suddenly look like giants."},{"id":"q7","question":"The Chapulín freezes his enemies in place by honking...","options":[{"id":"a","text":"A trumpet called the trumpeta paralizante","is_correct":false},{"id":"b","text":"A little horn called the chicharra paralizadora","is_correct":true},{"id":"c","text":"A bicycle bell called the timbre mágico","is_correct":false},{"id":"d","text":"A whistle called the silbato somnoliento","is_correct":false}],"explanation":"La chicharra paralizadora is a small horn: one honk and everyone freezes in place."},{"id":"q8","question":"Which recurring hero is the Chapulín''s rival, dressed in stars and stripes?","options":[{"id":"a","text":"Super Sam","is_correct":true},{"id":"b","text":"Captain Latin America","is_correct":false},{"id":"c","text":"El Santo","is_correct":false},{"id":"d","text":"The Green Grasshopper","is_correct":false}],"explanation":"Super Sam, an Uncle Sam-style superhero, competes with the Chapulín for every rescue."}]'::jsonb,
  null,
  array['el chapulin colorado', 'tv-shows', 'comedy', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
