values (
  'es-trivia-el-chapulin-colorado',
  'Trivia de El Chapulín Colorado: héroes y frases',
  'Más ágil que una tortuga, más fuerte que un ratón, más noble que una lechuga: El Chapulín Colorado, el superhéroe torpe de Chespirito. ¿Cuánto recuerdas de sus artilugios y frases?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"¿Quién creó e interpreta al Chapulín Colorado?","options":[{"id":"a","text":"Roberto Gómez Bolaños ''Chespirito''","is_correct":true},{"id":"b","text":"Édgar Vivar","is_correct":false},{"id":"c","text":"Rubén Aguirre","is_correct":false},{"id":"d","text":"Horacio Gómez Bolaños","is_correct":false}],"explanation":"Roberto Gómez Bolaños, Chespirito, es el Chapulín: el mismo creador de El Chavo del 8."},{"id":"q2","question":"¿Qué lleva el Chapulín en el pecho del traje?","options":[{"id":"a","text":"Un relámpago","is_correct":false},{"id":"b","text":"Un corazón con las letras CH","is_correct":true},{"id":"c","text":"Una estrella amarilla","is_correct":false},{"id":"d","text":"Un grillo rojo","is_correct":false}],"explanation":"Su escudo es un corazón, y así lo lleva dibujado: un corazón con las siglas CH."},{"id":"q3","question":"¿Qué grita el Chapulín cuando aparece para salvar a alguien?","options":[{"id":"a","text":"''¡No contaban con mi astucia!''","is_correct":true},{"id":"b","text":"''¡Fue sin querer queriendo!''","is_correct":false},{"id":"c","text":"''¡No me simpatizas!''","is_correct":false},{"id":"d","text":"''¡Tenía que ser el Chavo del 8!''","is_correct":false}],"explanation":"Su llegada se anuncia con ''¡No contaban con mi astucia!''; las demás frases son de la vecindad del Chavo."},{"id":"q4","question":"¿Qué es el Chipote Chillón?","options":[{"id":"a","text":"Una espada mágica","is_correct":false},{"id":"b","text":"Una resortera","is_correct":false},{"id":"c","text":"Un martillo chillón","is_correct":true},{"id":"d","text":"Un escudo","is_correct":false}],"explanation":"El Chipote Chillón es un pequeño martillo chillón con el que golpea a los villanos."},{"id":"q5","question":"¿Qué efecto tienen las pastillas de chiquitina?","options":[{"id":"a","text":"Lo vuelven invisible","is_correct":false},{"id":"b","text":"Lo hacen volar","is_correct":false},{"id":"c","text":"Lo vuelven diminuto","is_correct":true},{"id":"d","text":"Le dan superfuerza","is_correct":false}],"explanation":"Las pastillas de chiquitina lo reducen al tamaño de un muñeco."},{"id":"q6","question":"¿Para qué sirve la chicharra paralizadora?","options":[{"id":"a","text":"Para inmovilizar a sus enemigos","is_correct":true},{"id":"b","text":"Para comunicarse con la base","is_correct":false},{"id":"c","text":"Para hacerse invisible","is_correct":false},{"id":"d","text":"Para llamar a otros superhéroes","is_correct":false}],"explanation":"La chicharra paralizadora es una pequeña corneta: un solo toque deja congelado a quien la escucha."},{"id":"q7","question":"Según la presentación, el Chapulín es más ágil que...","options":[{"id":"a","text":"Un gato","is_correct":false},{"id":"b","text":"Una tortuga","is_correct":true},{"id":"c","text":"Un ratón","is_correct":false},{"id":"d","text":"Un conejo","is_correct":false}],"explanation":"''Más ágil que una tortuga, más fuerte que un ratón, más noble que una lechuga'': el ratón es el de la fuerza, no el de la agilidad."},{"id":"q8","question":"¿Cómo se llama el superhéroe rival del Chapulín que viste los colores de Estados Unidos?","options":[{"id":"a","text":"Super Ratón","is_correct":false},{"id":"b","text":"Super Sam","is_correct":true},{"id":"c","text":"El Capitán México","is_correct":false},{"id":"d","text":"El Justiciero Verde","is_correct":false}],"explanation":"Super Sam viste como el Tío Sam y compite con el Chapulín por cada rescate."}]'::jsonb,
