values (
  'en-classic-telenovelas-trivia',
  'Classic Telenovelas Trivia: Plots and Stars',
  'Evil twins, unforgettable villains and weddings that never go as planned: the classic Latin American telenovelas everyone watched with their family. How much do you remember?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"Which telenovela gave us the villain Soraya Montenegro and her immortal ''¡Maldita lisiada!''?","options":[{"id":"a","text":"La Usurpadora","is_correct":false},{"id":"b","text":"María la del Barrio","is_correct":true},{"id":"c","text":"Rosalinda","is_correct":false},{"id":"d","text":"Esmeralda","is_correct":false}],"explanation":"Soraya Montenegro, played by Itatí Cantoral, raged through María la del Barrio (1995)."},{"id":"q2","question":"Yo soy Betty, la Fea — the telenovela with the most remakes in the world — comes from which country?","options":[{"id":"a","text":"Mexico","is_correct":false},{"id":"b","text":"Venezuela","is_correct":false},{"id":"c","text":"Colombia","is_correct":true},{"id":"d","text":"Argentina","is_correct":false}],"explanation":"Betty la Fea premiered in Colombia in 1999 and has been adapted in dozens of countries, including as Ugly Betty in the US."},{"id":"q3","question":"In La Usurpadora (1998), who plays both twins, the sweet Paulina and the wicked Paola?","options":[{"id":"a","text":"Thalía","is_correct":false},{"id":"b","text":"Lucero","is_correct":false},{"id":"c","text":"Gabriela Spanic","is_correct":true},{"id":"d","text":"Dominika Paleta","is_correct":false}],"explanation":"Gabriela Spanic plays both Bracho twins; Dominika Paleta plays Gema in the same telenovela."},{"id":"q4","question":"Which of these telenovelas is part of Thalía''s ''María'' trilogy?","options":[{"id":"a","text":"Marimar","is_correct":true},{"id":"b","text":"Rosalinda","is_correct":false},{"id":"c","text":"Esmeralda","is_correct":false},{"id":"d","text":"Cuna de lobos","is_correct":false}],"explanation":"María Mercedes (1992), Marimar (1994) and María la del Barrio (1995) form the trilogy; Rosalinda is also a Thalía hit, but a separate story."},{"id":"q5","question":"Which 1979 telenovela turned Verónica Castro into an international star?","options":[{"id":"a","text":"Los Ricos También Lloran","is_correct":true},{"id":"b","text":"Cristal","is_correct":false},{"id":"c","text":"El Derecho de Nacer","is_correct":false},{"id":"d","text":"Rosa Salvaje","is_correct":false}],"explanation":"Verónica Castro starred as Mariana in Los Ricos También Lloran, one of the first telenovelas to conquer audiences far beyond Latin America."},{"id":"q6","question":"In Cuna de lobos (1986), which villainess is famous for her jeweled eye patch?","options":[{"id":"a","text":"Soraya Montenegro","is_correct":false},{"id":"b","text":"Catalina Creel","is_correct":true},{"id":"c","text":"Paola Bracho","is_correct":false},{"id":"d","text":"Rubí Pérez","is_correct":false}],"explanation":"Catalina Creel, played by Diana Bracho, is telenovela''s most iconic villain — eye patch included."},{"id":"q7","question":"In Esmeralda (1997), what is the heroine''s defining condition?","options":[{"id":"a","text":"She is blind","is_correct":true},{"id":"b","text":"She cannot speak","is_correct":false},{"id":"c","text":"She lost her memory","is_correct":false},{"id":"d","text":"She is deaf","is_correct":false}],"explanation":"Esmeralda, played by Leticia Calderón, is a blind young woman; the telenovela remade an earlier Venezuelan classic."}]'::jsonb,
  null,
  array['telenovelas', 'tv-shows', 'drama', 'trivia']::text[],
