insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-latin-tv-90s-trivia',
  '90s Latin TV Trivia: Shows and Openings',
  'Saturday giants, orphanage pop songs and late-night comedy: the Latin American TV shows that defined the 90s. How many can you still name?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"''Don Francisco'', the host of Sábado Gigante, is the stage name of...","options":[{"id":"a","text":"Mario Kreutzberger","is_correct":true},{"id":"b","text":"Raúl Velasco","is_correct":false},{"id":"c","text":"Xavier López","is_correct":false},{"id":"d","text":"Marcelo Tinelli","is_correct":false}],"explanation":"Mario Kreutzberger, a Chilean presenter, hosted Sábado Gigante for decades; Xavier López was ''Chabelo''."},{"id":"q2","question":"What is the name of the giant green parrot on Plaza Sésamo?","options":[{"id":"a","text":"Lola","is_correct":false},{"id":"b","text":"Pancho","is_correct":false},{"id":"c","text":"Abelardo","is_correct":true},{"id":"d","text":"Beto","is_correct":false}],"explanation":"Abelardo is the huge green parrot of Plaza Sésamo, the Latin American Sesame Street; Pancho, Lola and Beto are also characters on the show."},{"id":"q3","question":"Chiquititas, the Argentine series about a girls'' orphanage, was created by...","options":[{"id":"a","text":"Cris Morena","is_correct":true},{"id":"b","text":"Florinda Meza","is_correct":false},{"id":"c","text":"Gabriela Rivero","is_correct":false},{"id":"d","text":"Thalía","is_correct":false}],"explanation":"Cris Morena created Chiquititas in 1995 and built a whole empire of youth TV around it."},{"id":"q4","question":"Which host turned VideoMatch into Argentina''s biggest 90s variety show?","options":[{"id":"a","text":"Julián Weich","is_correct":false},{"id":"b","text":"Marcelo Tinelli","is_correct":true},{"id":"c","text":"Jorge Guinzburg","is_correct":false},{"id":"d","text":"Antonio Gasalla","is_correct":false}],"explanation":"Marcelo Tinelli hosted VideoMatch, the mix of comedy and games that dominated Argentine TV."},{"id":"q5","question":"Adal Ramones hosted which Mexican late-night show, launched in 1995?","options":[{"id":"a","text":"La Movida","is_correct":false},{"id":"b","text":"Siempre en Domingo","is_correct":false},{"id":"c","text":"Hoy","is_correct":false},{"id":"d","text":"Otro Rollo","is_correct":true}],"explanation":"Otro Rollo aired on Televisa from 1995 and became the reference for late-night comedy in Mexico."},{"id":"q6","question":"The Viña del Mar song festival, a staple of Latin American TV, takes place in which country?","options":[{"id":"a","text":"Argentina","is_correct":false},{"id":"b","text":"Mexico","is_correct":false},{"id":"c","text":"Chile","is_correct":true},{"id":"d","text":"Puerto Rico","is_correct":false}],"explanation":"Every February, the festival fills the Quinta Vergara amphitheater in Viña del Mar, Chile."},{"id":"q7","question":"Which Sunday variety show did Raúl Velasco host on Televisa for decades?","options":[{"id":"a","text":"Otro Rollo","is_correct":false},{"id":"b","text":"En familia con Chabelo","is_correct":false},{"id":"c","text":"Sábado Gigante","is_correct":false},{"id":"d","text":"Siempre en Domingo","is_correct":true}],"explanation":"Raúl Velasco''s Siempre en Domingo was a Sunday fixture for Mexican families; Chabelo had his own Sunday show, En familia con Chabelo."}]'::jsonb,
  null,
  array['latin-tv', 'tv-shows', '90s', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
