values (
  'es-trivia-programas-tv-latinos-90',
  'Trivia de programas de TV latinos de los 90',
  'Gigantes de los sábados, orfanatos musicales y humor de medianoche: la televisión latinoamericana que definió los años 90. ¿Cuántos programas recuerdas?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'pop-culture'),
  '[{"id":"q1","question":"¿Cómo se llamaba el presentador de Sábado Gigante?","options":[{"id":"a","text":"Raúl Velasco","is_correct":false},{"id":"b","text":"Don Francisco","is_correct":true},{"id":"c","text":"Adal Ramones","is_correct":false},{"id":"d","text":"Marcelo Tinelli","is_correct":false}],"explanation":"Don Francisco, cuyo nombre real es Mario Kreutzberger, condujo Sábado Gigante durante décadas."},{"id":"q2","question":"¿Cuál es el nombre del loro gigante verde de Plaza Sésamo?","options":[{"id":"a","text":"Abelardo","is_correct":true},{"id":"b","text":"Lola","is_correct":false},{"id":"c","text":"Pancho","is_correct":false},{"id":"d","text":"La rana René","is_correct":false}],"explanation":"Abelardo es el loro gigante de Plaza Sésamo, la versión latinoamericana de Sesame Street; la rana René es del programa original."},{"id":"q3","question":"¿Cómo se llama el orfanato donde viven las Chiquititas?","options":[{"id":"a","text":"Casa del Sol","is_correct":false},{"id":"b","text":"Rincón de Luz","is_correct":true},{"id":"c","text":"Villa Alegría","is_correct":false},{"id":"d","text":"Hogar Dulce Hogar","is_correct":false}],"explanation":"El Rincón de Luz es el hogar de las chicas en la serie que Cris Morena creó en 1995."},{"id":"q4","question":"¿Quién condujo VideoMatch, el gran programa de variedades argentino de los 90?","options":[{"id":"a","text":"Julián Weich","is_correct":false},{"id":"b","text":"Antonio Gasalla","is_correct":false},{"id":"c","text":"Jorge Guinzburg","is_correct":false},{"id":"d","text":"Marcelo Tinelli","is_correct":true}],"explanation":"Marcelo Tinelli hizo de VideoMatch el programa de humor y juegos que dominaba la televisión argentina."},{"id":"q5","question":"¿Qué programa infantil chileno tenía al títere Cholo y al ''tío Marcelo''?","options":[{"id":"a","text":"Plaza Sésamo","is_correct":false},{"id":"b","text":"Cachureos","is_correct":true},{"id":"c","text":"31 Minutos","is_correct":false},{"id":"d","text":"Chiquititas","is_correct":false}],"explanation":"Cachureos se emitió en TVN desde 1986 y marcó a los niños chilenos de los 90; 31 Minutos llegó recién en 2003."},{"id":"q6","question":"¿En qué ciudad chilena se celebra el festival de la Quinta Vergara?","options":[{"id":"a","text":"Santiago","is_correct":false},{"id":"b","text":"Valparaíso","is_correct":false},{"id":"c","text":"Viña del Mar","is_correct":true},{"id":"d","text":"Concepción","is_correct":false}],"explanation":"El Festival de Viña del Mar llena la Quinta Vergara cada febrero."},{"id":"q7","question":"¿Qué programa familiar de los domingos conducía Xavier López ''Chabelo''?","options":[{"id":"a","text":"Siempre en Domingo","is_correct":false},{"id":"b","text":"Sábado Gigante","is_correct":false},{"id":"c","text":"Otro Rollo","is_correct":false},{"id":"d","text":"En familia con Chabelo","is_correct":true}],"explanation":"En familia con Chabelo acompañó los domingos de Televisa durante décadas; Siempre en Domingo era el programa de Raúl Velasco."}]'::jsonb,
  null,
  array['television-latina', 'series', 'noventas', 'trivia']::text[],
