insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-latin-dubbing-voices-trivia',
  'Latin Dubbing Trivia: The Voices Behind the Icons',
  'Goku, Homer Simpson and Sailor Moon all speak with famous Mexican voices: the Latin American dubbing actors behind the icons. Can you match each voice to its character?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"Who is the Latin American Spanish voice of Goku in Dragon Ball Z?","options":[{"id":"a","text":"René García","is_correct":false},{"id":"b","text":"Mario Castañeda","is_correct":true},{"id":"c","text":"Eduardo Garza","is_correct":false},{"id":"d","text":"Gerardo Reyero","is_correct":false}],"explanation":"Mario Castañeda voices adult Goku; René García is Vegeta, Eduardo Garza is Krillin and Gerardo Reyero is Frieza in the same dub."},{"id":"q2","question":"And who dubs Vegeta in that same legendary cast?","options":[{"id":"a","text":"Carlos Segundo","is_correct":false},{"id":"b","text":"Gerardo Reyero","is_correct":false},{"id":"c","text":"Mario Castañeda","is_correct":false},{"id":"d","text":"René García","is_correct":true}],"explanation":"René García is Vegeta''s Latin voice; Carlos Segundo is Piccolo and Gerardo Reyero is Frieza."},{"id":"q3","question":"Which actor gave Woody his Latin Spanish voice in Toy Story?","options":[{"id":"a","text":"Carlos Segundo","is_correct":true},{"id":"b","text":"Mario Filio","is_correct":false},{"id":"c","text":"Humberto Vélez","is_correct":false},{"id":"d","text":"Jesús Barrero","is_correct":false}],"explanation":"Carlos Segundo voiced Woody — and Piccolo in Dragon Ball Z, another of his signature roles."},{"id":"q4","question":"The classic Latin Spanish voice of Homer Simpson is...","options":[{"id":"a","text":"Gabriel Chávez","is_correct":false},{"id":"b","text":"Humberto Vélez","is_correct":true},{"id":"c","text":"Mario Castañeda","is_correct":false},{"id":"d","text":"Eduardo Garza","is_correct":false}],"explanation":"Humberto Vélez voiced Homer in the dub''s classic era; Gabriel Chávez voiced Mr. Burns in the same cast."},{"id":"q5","question":"Which actress dubbed both Sailor Moon and Lisa Simpson in Latin Spanish?","options":[{"id":"a","text":"Cristina Hernández","is_correct":false},{"id":"b","text":"Xóchitl Ugarte","is_correct":false},{"id":"c","text":"Isabel Martiñón","is_correct":false},{"id":"d","text":"Patricia Acevedo","is_correct":true}],"explanation":"Patricia Acevedo is the Latin voice of Sailor Moon and of Lisa Simpson; Cristina Hernández voiced Sakura in Cardcaptors."},{"id":"q6","question":"Who was the original Latin Spanish voice of Ash Ketchum in Pokémon?","options":[{"id":"a","text":"Gabriel Ramos","is_correct":true},{"id":"b","text":"Eduardo Garza","is_correct":false},{"id":"c","text":"Mario Filio","is_correct":false},{"id":"d","text":"Jesús Barrero","is_correct":false}],"explanation":"Gabriel ''Gabo'' Ramos dubbed Ash for years; in the same cast, Xóchitl Ugarte voiced Misty."},{"id":"q7","question":"Which actor dubbed both Seiya in Knights of the Zodiac and Luke Skywalker in Star Wars?","options":[{"id":"a","text":"Mario Castañeda","is_correct":false},{"id":"b","text":"René García","is_correct":false},{"id":"c","text":"Jesús Barrero","is_correct":true},{"id":"d","text":"Gabriel Ramos","is_correct":false}],"explanation":"Jesús Barrero voiced Seiya and Luke Skywalker — two of the most beloved heroes of a generation."}]'::jsonb,
  null,
  array['dubbing', 'voice-acting', 'anime', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

